exercises.solution:
SIGNAUX = {
    "urgence": ["urgent", "immédiatement", "dernier délai"],
    "argent": ["envoie", "transfert", "mobile money", "frais"],
    "code": ["code", "mot de passe"],
    "lien": ["bit.ly", "cliquez"],
}


def signaux(message):
    texte = message.lower()
    return [nom for nom, indices in SIGNAUX.items() if any(i in texte for i in indices)]


def niveau(message):
    n = len(signaux(message))
    return "élevé" if n >= 2 else "moyen" if n == 1 else "faible"


def conseil(message, numero_connu):
    trouves = signaux(message)
    if "code" in trouves:
        return "Ne donne jamais ce code."
    if niveau(message) == "élevé" or (not numero_connu and trouves):
        return "Vérifie par un autre canal."
    return "Aucun signal particulier."
